contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 points, address caller) public {
        uint256 beforeFighterPoints = c.fighterPoints(tokenId);
        uint256 beforeTotalPoints = c.totalPoints();

        bool reverted;
        if (caller == address(this)) {
            try c.addPoints(tokenId, points) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool success, ) = address(c).call(
                abi.encodeWithSelector(c.addPoints.selector, tokenId, points)
            );
            reverted = !success;
        }

        uint256 afterFighterPoints = c.fighterPoints(tokenId);
        uint256 afterTotalPoints = c.totalPoints();

        if (!reverted) {
            assert(afterFighterPoints == beforeFighterPoints + points);
            assert(afterTotalPoints == beforeTotalPoints + points);
        }
    }
}

