contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners, uint32 beforeClaimIndex) public {
        // Read before-state of the winners snapshot sum
        uint256 beforeSum = 0;
        for (uint256 i = 0; i < c.roundId(); i++) {
            uint256 len = 0;
            while (true) {
                (address a) = c.winnerAddresses(i, len);
                if (a == address(0)) break;
                len++;
            }
            beforeSum += len;
        }

        // Try the state-changing call (may or may not be allowed depending on admin/winners setup)
        bool reverted;
        try c.claimRewards(new string[](0), new string[](0), new uint256[2][](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state of the winners snapshot sum
        uint256 afterSum = 0;
        for (uint256 i = 0; i < c.roundId(); i++) {
            uint256 len = 0;
            while (true) {
                (address a) = c.winnerAddresses(i, len);
                if (a == address(0)) break;
                len++;
            }
            afterSum += len;
        }

        assert(afterSum == beforeSum);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public {
        uint256 winnersPerPeriod = c.winnersPerPeriod();
        require(winners.length == winnersPerPeriod, "winners length mismatch");

        uint256 beforeSum = 0;
        uint256 r = 0;
        while (true) {
            (address a0, ) = c.winnerAddresses(r, 0);
            if (a0 == address(0)) break;
            uint256 len = 1;
            while (true) {
                (address ai, ) = c.winnerAddresses(r, len);
                if (ai == address(0)) break;
                len++;
            }
            beforeSum += len;
            r++;
        }

        bool reverted;
        try c.claimRewards(new string[](0), new string[](0), new uint256[2][](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSum = 0;
        uint256 r2 = 0;
        while (true) {
            (address a0, ) = c.winnerAddresses(r2, 0);
            if (a0 == address(0)) break;
            uint256 len = 1;
            while (true) {
                (address ai, ) = c.winnerAddresses(r2, len);
                if (ai == address(0)) break;
                len++;
            }
            afterSum += len;
            r2++;
        }

        assert(afterSum == beforeSum);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        uint256 beforeRoundId = c.roundId();
        uint32 beforeClaimed = c.numRoundsClaimed(address(this));

        address[2] memory before0 = c.winnerAddresses(0, 0);
        address[2] memory before1 = c.winnerAddresses(0, 1);

        bool reverted;
        try c.claimRewards(new string[](0), new string[](0), new uint256[2][](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRoundId = c.roundId();
        uint32 afterClaimed = c.numRoundsClaimed(address(this));
        address[2] memory after0 = c.winnerAddresses(0, 0);
        address[2] memory after1 = c.winnerAddresses(0, 1);

        bool winnersUnchanged = before0[0] == after0[0] && before0[1] == after0[1]
            && before1[0] == after1[0] && before1[1] == after1[1];

        if (reverted) {
            assert(afterRoundId == beforeRoundId && afterClaimed == beforeClaimed && winnersUnchanged);
        } else {
            uint32 expectedClaimed = beforeClaimed + uint32(beforeRoundId);
            assert(afterClaimed == expectedClaimed && afterRoundId == beforeRoundId && winnersUnchanged);
        }
    }

    receive() external payable {}
}

