        } catch {
            reverted = true;
        }

        uint256 afterRoundId = c.roundId();
        uint32 afterClaimed = c.numRoundsClaimed(address(this));

        bool winnersUnchanged = true;
        {
            address[] memory afterWinners0 = new address[](c.winnerAddresses(0).length);
            for (uint256 i = 0; i < afterWinners0.length; i++) {
                afterWinners0[i] = c.winnerAddresses(0, i);
            }
            if (afterWinners0.length != beforeWinners0.length) {
                winnersUnchanged = false;
            } else {
                for (uint256 i = 0; i < afterWinners0.length; i++) {
                    if (afterWinners0[i] != beforeWinners0[i]) {
                        winnersUnchanged = false;
                    }
                }
            }
            address[] memory afterWinners1 = new address[](c.winnerAddresses(1).length);
            for (uint256 i = 0; i < afterWinners1.length; i++) {
                afterWinners1[i] = c.winnerAddresses(1, i);
            }
            if (afterWinners1.length != beforeWinners1.length) {
                winnersUnchanged = false;
            } else {
                for (uint256 i = 0; i < afterWinners1.length; i++) {
                    if (afterWinners1[i] != beforeWinners1[i]) {
                        winnersUnchanged = false;
                    }
                }
            }
        }

        uint32 expectedClaimed = beforeClaimed + uint32(beforeRoundId);

        assert(
            !reverted &&
            afterRoundId == beforeRoundId &&
            afterClaimed == expectedClaimed &&
            winnersUnchanged
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address admin,
        address claimer,
        uint256 newWinnersPerPeriod,
        uint256[] calldata winners,
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public {
        c.adjustAdminAccess(admin, true);
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        c.pickWinner(winners);

        uint256 beforeRoundsClaimed = c.numRoundsClaimed(claimer);
        uint256 beforeUnclaimed = c.getUnclaimedRewards(claimer);
        uint256 beforeRoundId = c.roundId();

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRoundsClaimed = c.numRoundsClaimed(claimer);

        if (!reverted) {
            assert(afterRoundsClaimed <= beforeRoundId);
            assert(beforeUnclaimed == 0);
        } else {
            assert(afterRoundsClaimed == beforeRoundsClaimed);
        }
    }

    receive() external payable {}
}

