    constructor(C _c) {
        c = _c;
    }

    function run(address claimer, uint256 roundIdBefore) public payable {
        require(roundIdBefore == c.roundId());

        uint256 unclaimedBefore = c.getUnclaimedRewards(claimer);
        uint32 claimedBefore = c.numRoundsClaimed(claimer);
        uint256 roundIdAfterBefore = c.roundId();

        string[] memory modelURIs = new string[](0);
        string[] memory modelTypes = new string[](0);
        uint256[2][] memory customAttributes = new uint256[2][](0);

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 roundIdAfter = c.roundId();
        uint32 claimedAfter = c.numRoundsClaimed(claimer);
        uint256 unclaimedAfter = c.getUnclaimedRewards(claimer);

        assert(
            roundIdAfter >= roundIdAfterBefore &&
            claimedAfter >= claimedBefore &&
            claimedAfter <= uint32(roundIdAfter) &&
            unclaimedAfter <= unclaimedBefore &&
            (reverted || claimedAfter == uint32(roundIdAfter))
        );
    }

    receive() external payable {}
}

