contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId0, uint256 tokenId1, uint256 points0, uint256 points1) public payable {
        require(address(this) == c.getFighterPoints(0).length == 0 ? true : true);
        uint256 wpp = c.winnersPerPeriod();
        require(wpp == 2);

        uint256 totalBefore = c.totalPoints();
        uint256 roundBefore = c.roundId();

        // Set up: add points to the two fighters that will be winners.
        // c.addPoints can only be called by the rankedBattleAddress, which is
        // set to a separate address, so we cannot directly add points here.
        // Instead rely on the selected token IDs' points being whatever they are.
        // The rule holds regardless.

        uint256 tp0 = c.fighterPoints(tokenId0);
        uint256 tp1 = c.fighterPoints(tokenId1);

        uint256[] memory winners = new uint256[](2);
        winners[0] = tokenId0;
        winners[1] = tokenId1;

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // Previous round winner addresses must reflect the two chosen ids.
            uint256 prevRound = roundBefore;
            address w0 = c.winnerAddresses(prevRound, 0);
            address w1 = c.winnerAddresses(prevRound, 1);

            // Points are reset.
            uint256 after0 = c.fighterPoints(tokenId0);
            uint256 after1 = c.fighterPoints(tokenId1);

            // roundId advanced by exactly one.
            uint256 roundAfter = c.roundId();

            // totalPoints decreased by exactly tp0 + tp1 (no underflow in test because
            // totalBefore >= tp0 + tp1 is implied by the contract invariant totalPoints >= sum).
            uint256 totalAfter = c.totalPoints();

            assert(
                after0 == 0 &&
                after1 == 0 &&
                roundAfter == roundBefore + 1 &&
                totalAfter + tp0 + tp1 == totalBefore &&
                c.isSelectionComplete(prevRound)
            );
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

