contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 winnersPerPeriod_, uint256[] calldata expectedWins) public payable {
        require(winnersPerPeriod_ > 0, "winnersPerPeriod must be positive");
        require(expectedWins.length == winnersPerPeriod_, "expectedWins length must equal winnersPerPeriod");
        require(address(this).balance >= 0, "balance check");

        // Set winnersPerPeriod through the admin path (test contract is the owner/admin).
        c.updateWinnersPerPeriod(winnersPerPeriod_);

        // Capture observable before values.
        uint256 roundIdBefore = c.roundId();
        uint256 totalPointsBefore = c.totalPoints();
        address self = address(this);

        // New address has no claimed rounds yet.
        require(c.numRoundsClaimed(self) == 0, "fresh address claimed rounds nonzero");

        uint256 unclaimedBefore = c.getUnclaimedRewards(self);
        require(unclaimedBefore == 0, "fresh address has unexpected unclaimed rewards");

        // No winners have been picked yet, so the expected-wins array must be empty.
        require(expectedWins.length == 0, "no rounds yet, expectedWins must be empty");
        uint256[] memory winners = new uint256[](0);

        // Pick no winners for the current round. This increments roundId.
        c.pickWinner(winners);

        // After pickWinner, exactly one round has been processed.
        uint256 roundIdAfter = c.roundId();

        // The claim/reward surface should be consistent for the fresh address.
        uint256 unclaimedAfter = c.getUnclaimedRewards(self);

        string[] memory modelURIs = new string[](0);
        string[] memory modelTypes = new string[](0);
        uint256[2][] memory customAttributes = new uint256[2][](0);

        bool reverted;
        try c.claimRewards(modelURIs, modelTypes, customAttributes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 claimedRoundsAfter = c.numRoundsClaimed(self);

        assert(
            unclaimedBefore == 0 &&
            unclaimedAfter == 0 &&
            !reverted &&
            roundIdAfter == roundIdBefore + 1 &&
            c.totalPoints() == totalPointsBefore &&
            claimedRoundsAfter == 0
        );
    }

    receive() external payable {}
}

