contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        uint256 roundIdBefore = c.roundId();
        uint256 totalPointsBefore = c.totalPoints();

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 winnersPerPeriodAfter = c.winnersPerPeriod();
        uint256 roundIdAfter = c.roundId();
        uint256 totalPointsAfter = c.totalPoints();
        bool isSelectionCompleteForOldRound = c.isSelectionComplete(roundIdBefore);

        if (reverted) {
            assert(
                roundIdAfter == roundIdBefore &&
                totalPointsAfter == totalPointsBefore &&
                !isSelectionCompleteForOldRound &&
                winnersPerPeriodAfter == winnersPerPeriodBefore
            );
        } else {
            assert(
                winnersPerPeriodAfter == winnersPerPeriodBefore &&
                winners.length == winnersPerPeriodBefore &&
                roundIdAfter == roundIdBefore + 1 &&
                isSelectionCompleteForOldRound &&
                c.isSelectionComplete(roundIdAfter - 1) &&
                !c.isSelectionComplete(roundIdAfter)
            );
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        uint256 winnersPerPeriodBefore = c.winnersPerPeriod();
        uint256 roundIdBefore = c.roundId();
        uint256 totalPointsBefore = c.totalPoints();

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 winnersPerPeriodAfter = c.winnersPerPeriod();
        uint256 roundIdAfter = c.roundId();
        uint256 totalPointsAfter = c.totalPoints();
        bool selectionCompleteOld = c.isSelectionComplete(roundIdBefore);
        bool selectionCompleteNew = c.isSelectionComplete(roundIdAfter);

        assert(
            reverted
                ? (roundIdAfter == roundIdBefore &&
                    totalPointsAfter == totalPointsBefore &&
                    !selectionCompleteOld &&
                    winnersPerPeriodAfter == winnersPerPeriodBefore)
                : (winnersPerPeriodAfter == winnersPerPeriodBefore &&
                    winners.length == winnersPerPeriodBefore &&
                    roundIdAfter == roundIdBefore + 1 &&
                    selectionCompleteOld &&
                    !selectionCompleteNew)
        );
    }
